<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$user=current_user($pdo);$s=$pdo->prepare('SELECT e.*,u.full_name AS creator_name FROM events e JOIN users u ON u.id=e.user_id WHERE e.event_date>=NOW() OR e.user_id=? ORDER BY e.event_date ASC');$s->execute([$user['id']]);$events=$s->fetchAll();$page_title='Dashboard';require __DIR__.'/includes/header.php'; ?>
<div class="dashboard-grid"><section class="panel"><h1>Your Dashboard</h1><p>Manage events, search users/events, and message others.</p><div class="actions"><a class="button" href="event_create.php">+ Create Event</a><a class="button" href="search.php">Search</a><a class="button" href="messages.php">Messages</a></div><hr><h2>Your Events & Upcoming Events</h2><?php if(!$events): ?><p class="muted">No events yet. Create your first event to get started.</p><?php else: ?><div class="event-list"><?php foreach($events as $event): ?><article class="event-row"><div><h3><?= e($event['title']) ?></h3><p><?= e($event['description']) ?></p><small><?= e(date('D, d M Y · H:i',strtotime($event['event_date']))) ?> · <?= e($event['location']) ?> · by <?= e($event['creator_name']) ?></small></div><?php if((int)$event['user_id']===(int)$user['id']): ?><div class="actions compact"><a class="button small" href="event_edit.php?id=<?= (int)$event['id'] ?>">Edit</a><form method="post" action="event_delete.php" data-confirm="Delete this event? This cannot be undone."><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$event['id'] ?>"><button class="button small danger" type="submit">Delete</button></form></div><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section><aside class="panel"><h2>Security Checklist</h2><ul class="checklist"><li>Prepared statements for SQL injection prevention</li><li>Output escaping to prevent XSS</li><li>CSRF tokens on forms</li><li>Validated image uploads</li><li>Session-protected pages</li></ul><hr><h2>Your Profile</h2><div class="profile-mini"><img src="<?= avatar($user) ?>" alt="Profile picture"><div><strong><?= e($user['full_name']) ?></strong><p><?= e($user['email']) ?></p><a href="profile.php">View / update profile</a></div></div></aside></div><?php require __DIR__.'/includes/footer.php'; ?>